impl VectorAluOp {
    /// Every operation, in registry order.
    pub const ALL: [Self; 12] = [
        Self::MulI32I24,
        Self::MulHiI32I24,
        Self::MulU32U24,
        Self::MulHiU32U24,
        Self::MinI32,
        Self::MaxI32,
        Self::MinU32,
        Self::MaxU32,
        Self::XnorB32,
        Self::AddNcU32,
        Self::SubNcU32,
        Self::SubrevNcU32,
    ];

    /// Selects the operation from a first instruction word: the VOP2 encoding
    /// bits (mask 0x8000_0000) and then the OP field (bits 25-30).
    pub const fn from_word(word: u32) -> Option<Self> {
        if word & 0x8000_0000 != 0x0000_0000 {
            return None;
        }
        VECTOR_ALU_OP_BY_OPCODE[((word >> 25) & 0x3f) as usize]
    }

    /// Lower-case mnemonic.
    pub const fn mnemonic(self) -> &'static str {
        match self {
            Self::MulI32I24 => "v_mul_i32_i24",
            Self::MulHiI32I24 => "v_mul_hi_i32_i24",
            Self::MulU32U24 => "v_mul_u32_u24",
            Self::MulHiU32U24 => "v_mul_hi_u32_u24",
            Self::MinI32 => "v_min_i32",
            Self::MaxI32 => "v_max_i32",
            Self::MinU32 => "v_min_u32",
            Self::MaxU32 => "v_max_u32",
            Self::XnorB32 => "v_xnor_b32",
            Self::AddNcU32 => "v_add_nc_u32",
            Self::SubNcU32 => "v_sub_nc_u32",
            Self::SubrevNcU32 => "v_subrev_nc_u32",
        }
    }

    /// The validated registry row.
    pub fn semantics(self) -> &'static FormSemantics {
        &FORMS[match self {
            Self::MulI32I24 => 56,
            Self::MulHiI32I24 => 57,
            Self::MulU32U24 => 58,
            Self::MulHiU32U24 => 59,
            Self::MinI32 => 60,
            Self::MaxI32 => 61,
            Self::MinU32 => 62,
            Self::MaxU32 => 63,
            Self::XnorB32 => 64,
            Self::AddNcU32 => 65,
            Self::SubNcU32 => 66,
            Self::SubrevNcU32 => 67,
        }]
    }

    /// Assembler name of the 32-bit (VOP2) encoding, as LLVM prints it.
    pub const fn assembly_name(self) -> &'static str {
        match self {
            Self::MulI32I24 => "v_mul_i32_i24_e32",
            Self::MulHiI32I24 => "v_mul_hi_i32_i24_e32",
            Self::MulU32U24 => "v_mul_u32_u24_e32",
            Self::MulHiU32U24 => "v_mul_hi_u32_u24_e32",
            Self::MinI32 => "v_min_i32_e32",
            Self::MaxI32 => "v_max_i32_e32",
            Self::MinU32 => "v_min_u32_e32",
            Self::MaxU32 => "v_max_u32_e32",
            Self::XnorB32 => "v_xnor_b32_e32",
            Self::AddNcU32 => "v_add_nc_u32_e32",
            Self::SubNcU32 => "v_sub_nc_u32_e32",
            Self::SubrevNcU32 => "v_subrev_nc_u32_e32",
        }
    }

    /// The per-lane operation its MSL lowering uses.
    pub const fn lowering(self) -> VectorBinary {
        match self {
            Self::MulI32I24 => VectorBinary::Mul24Signed,
            Self::MulHiI32I24 => VectorBinary::MulHi24Signed,
            Self::MulU32U24 => VectorBinary::Mul24Unsigned,
            Self::MulHiU32U24 => VectorBinary::MulHi24Unsigned,
            Self::MinI32 => VectorBinary::MinSigned,
            Self::MaxI32 => VectorBinary::MaxSigned,
            Self::MinU32 => VectorBinary::MinUnsigned,
            Self::MaxU32 => VectorBinary::MaxUnsigned,
            Self::XnorB32 => VectorBinary::Xnor,
            Self::AddNcU32 => VectorBinary::Add,
            Self::SubNcU32 => VectorBinary::Sub,
            Self::SubrevNcU32 => VectorBinary::Sub,
        }
    }

    /// Whether the operation reads its sources reversed (`D = op(S1, S0)`).
    pub const fn swaps_sources(self) -> bool {
        match self {
            Self::MulI32I24 => false,
            Self::MulHiI32I24 => false,
            Self::MulU32U24 => false,
            Self::MulHiU32U24 => false,
            Self::MinI32 => false,
            Self::MaxI32 => false,
            Self::MinU32 => false,
            Self::MaxU32 => false,
            Self::XnorB32 => false,
            Self::AddNcU32 => false,
            Self::SubNcU32 => false,
            Self::SubrevNcU32 => true,
        }
    }
}

